import requests
from typing import Any, Optional

def http_request(
    method: str,
    url: str,
    data: Optional[dict] = None,
    params: Optional[dict] = None
) -> Optional[Any]:
    try:
        if method.upper() == 'GET':
            response = requests.get(url, params=params)
            ok = 200
        elif method.upper() == 'POST':
            response = requests.post(url, data=data)
            ok = 201
        else:
            raise ValueError('Unsupported method')
        if response.status_code == ok:
            return response.json()
        return None
    except requests.RequestException:
        return None

import requests
import json

def fetch_data(url, headers=None):
    try:
        response = requests.get(url, headers=headers, timeout=10)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        return {'error': str(e)}

def submit_data(url, payload, headers=None):
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=10)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        return {'error': str(e)}

if __name__ == '__main__':
    get_url = 'https://httpbin.org/get'
    post_url = 'https://httpbin.org/post'

    result_get = fetch_data(get_url, headers={'User-Agent': 'CodolingoClient'})
    result_post = submit_data(post_url, payload={'action': 'login'}, headers={'Content-Type': 'application/json'})

    print('GET result:', json.dumps(result_get, indent=2))
    print('POST result:', json.dumps(result_post, indent=2))

import requests

BASE_URL = 'https://api.university.edu/v1'
HEADERS = {'Authorization': 'Bearer demo_token'}

def get_courses():
    try:
        response = requests.get(f'{BASE_URL}/courses', headers=HEADERS, timeout=10)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print('Failed to fetch courses:', e)
        return []

def enroll_student(student_id, course_id):
    try:
        payload = {'student_id': student_id, 'course_id': course_id}
        response = requests.post(f'{BASE_URL}/enrollments', json=payload, headers=HEADERS, timeout=10)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print('Enrollment failed:', e)
        return None

if __name__ == '__main__':
    courses = get_courses()
    result = enroll_student(101, 501)
    print('Courses:', courses)
    print('Enrollment result:', result)
    print('Enrollment submitted.')

