import requests

class HttpClient:
    def __init__(self, base_url='', headers=None, timeout=10):
        self.base_url = base_url
        self.headers = headers or {}
        self.timeout = timeout
        self._last_response = None

    def get(self, endpoint, params=None):
        url = f'{self.base_url}{endpoint}'
        try:
            response = requests.get(url, headers=self.headers, params=params, timeout=self.timeout)
            response.raise_for_status()
            self._last_response = response
            return response.json()
        except requests.exceptions.RequestException as e:
            self._last_response = {'error': str(e)}
            return None

    def post(self, endpoint, payload=None):
        url = f'{self.base_url}{endpoint}'
        try:
            response = requests.post(url, headers=self.headers, json=payload, timeout=self.timeout)
            response.raise_for_status()
            self._last_response = response
            return response.json()
        except requests.exceptions.RequestException as e:
            self._last_response = {'error': str(e)}
            return None

    def last_response(self):
        if self._last_response is None:
            return {}
        return {
            'status_code': self._last_response.status_code,
            'headers': dict(self._last_response.headers),
            'url': self._last_response.url
        }

if __name__ == '__main__':
    client = HttpClient(base_url='https://httpbin.org', headers={'X-Client': 'Mastery'})
    data = client.get('/get')
    print(data)
    client.post('/post', {'key': 'value'})
    print(client.last_response())
